/**
 * WCAG 2.2 relative luminance and contrast ratio (`ui_ux/tokens.py`), as the brand book's colour page and checks use
 * them. Python's `** 2.4` (libm pow) and V8's differ by one ulp for some channels, so the 256 linearized values are
 * a table generated by Python (`SRGB_LINEAR`); the divisions and sums are plain IEEE arithmetic and agree.
 */
import { SRGB_LINEAR } from './python-unicode';
import { cpSlice, pyRepr, pyRound } from './python';

/** Python's `int(text, 16)` error for text that is not hexadecimal. */
export class HexValueError extends Error {
  override name = 'ValueError';
}

const HEX_DIGITS = /^[0-9a-fA-F]+$/;

/**
 * `int(h[i:i+2], 16)`. Python's `int()` also accepts signs, surrounding whitespace and underscores; those lax forms
 * are refused here (recorded as "Python accepts, TS refuses" cases in the fixture).
 */
function channel(slice: string): number {
  if (!HEX_DIGITS.test(slice)) throw new HexValueError(`invalid literal for int() with base 16: ${pyRepr(slice)}`);
  return parseInt(slice, 16);
}

function channels(hexValue: string): [number, number, number] {
  const h = hexValue.replace(/^#+/, '');
  return [channel(cpSlice(h, 0, 2)), channel(cpSlice(h, 2, 4)), channel(cpSlice(h, 4, 6))];
}

/** `lin(value / 255)` for an 8-bit channel value. */
export function linearChannel(value: number): number {
  return SRGB_LINEAR[value] ?? Number.NaN;
}

export function relativeLuminance(hexValue: string): number {
  const [r, g, b] = channels(hexValue).map(linearChannel) as [number, number, number];
  return 0.2126 * r + 0.7152 * g + 0.0722 * b;
}

export function wcagContrastRatio(foreground: string, background: string): number {
  const a = relativeLuminance(foreground);
  const b = relativeLuminance(background);
  return pyRound((Math.max(a, b) + 0.05) / (Math.min(a, b) + 0.05), 2);
}
